async ({ workspace: { search, edit } }) => {
  const s = await search("      - name: Run pi-action", { path: ".github/workflows/pi-assistant.yml" });
  const s2 = await search("extensions: github:cv/pit#v0.37.0", { path: ".github/workflows/pi-assistant.yml", contextLines: 1 });
  const m = s.matches[0], m2 = s2.matches[0];
  const step = `      # A PR labelled pi:pit-from-pr runs pi with that PR's Pit, pinned to its head commit when the job
      # starts, so a change to Pit can be tried on a real thread before it is merged and released. Only
      # same-repository PRs qualify, and only people with triage access can add the label.
      - name: Choose the Pit extension
        id: pit
        env:
          GH_TOKEN: \${{ steps.app.outputs.token }}
          REPO: \${{ github.repository }}
          NUMBER: \${{ github.event.issue.number || github.event.pull_request.number }}
          IS_PR: \${{ github.event.pull_request != null || github.event.issue.pull_request != null }}
          RELEASED: github:cv/pit#v0.37.0
        run: |
          extension="$RELEASED"
          if [ "$IS_PR" = "true" ]; then
            read -r head sha labelled < <(gh api "repos/$REPO/pulls/$NUMBER" \\
              --jq '[.head.repo.full_name // "", .head.sha, (any(.labels[]; .name == "pi:pit-from-pr"))] | @tsv')
            if [ "$labelled" = "true" ] && [ "$head" = "$REPO" ]; then
              extension="github:$REPO#$sha"
              echo "::notice title=Pit under test::PR #$NUMBER is labelled pi:pit-from-pr: loading $extension"
            fi
          fi
          echo "extension=$extension" >> "$GITHUB_OUTPUT"

`;
  return edit(".github/workflows/pi-assistant.yml", {
    revision: s.matches[0].revision,
    changes: [
      { kind: "insertBefore", anchor: m.anchor, content: step },
      { kind: "replace", start: m2.anchor, content: "          extensions: ${{ steps.pit.outputs.extension }}" },
    ],
  });
}
